mapper.select:
SELECT
MSGFILE_SHORTMSG
FROM MSGFILE
WHERE MSGFILE_CHANNEL = #{msgfileChannel,jdbcType=DECIMAL}
AND MSGFILE_ATM = #{msgfileErrorcode,jdbcType=CHAR}

SELECT

,

FROM MSGFILE


		AND MSGFILE_CHANNEL = #{args.msgfileChannel,jdbcType=DECIMAL}


		AND MSGFILE_ERRORCODE LIKE CONCAT('%', CONCAT(#{args.msgfileErrorcode}, '%'))


		AND MSGFILE_SUBSYS = #{args.msgfileSubsys,jdbcType=DECIMAL}


		AND MSGFILE_SEVERITY = #{args.msgfileSeverity,jdbcType=VARCHAR}


		AND MSGFILE_SHORTMSG LIKE CONCAT('%', CONCAT(#{args.msgfileShortmsg}, '%'))

SELECT

,

FROM (
SELECT M.*
FROM MSGFILE M
LEFT JOIN CHANNEL C ON M.MSGFILE_CHANNEL = C.CHANNEL_CHANNELNO


		AND MSGFILE_CHANNEL = #{args.msgfileChannel,jdbcType=DECIMAL}


		AND MSGFILE_ERRORCODE LIKE CONCAT('%', CONCAT(#{args.msgfileErrorcode}, '%'))


		AND MSGFILE_SUBSYS = #{args.msgfileSubsys,jdbcType=DECIMAL}


		AND MSGFILE_SEVERITY = #{args.msgfileSeverity,jdbcType=VARCHAR}


		AND MSGFILE_SHORTMSG LIKE CONCAT('%', CONCAT(#{args.msgfileShortmsg}, '%'))


)
